#!/usr/bin/env python3
import sys,json,argparse,re
from csvformat import parse_csv,write_csv

class QueryError(Exception): pass

def walk_recursive(node,key,out):
    if isinstance(node,dict):
        if key in node: out.append(node[key])
        for v in node.values(): walk_recursive(v,key,out)
    elif isinstance(node,list):
        for v in node: walk_recursive(v,key,out)

def split_path(s):
    parts=[]; cur=''; depth=0; quote=None; esc=False
    for c in s:
        if quote:
            cur+=c
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        elif c in '\"\'': quote=c; cur+=c
        elif c=='[': depth+=1; cur+=c
        elif c==']': depth-=1; cur+=c
        elif c=='.' and depth==0: parts.append(cur); cur=''
        else: cur+=c
    if cur: parts.append(cur)
    return parts

def evalq(data,q):
    q=q.strip()
    if not q: return data
    if q.startswith('..'):
        key=q[2:].strip(' .')
        if not key: raise QueryError('failed to parse selector')
        out=[]; walk_recursive(data,key,out); return out
    if q in ('keys()','values()'):
        if not isinstance(data,dict): raise QueryError('function requires a map')
        return list(data.keys()) if q=='keys()' else list(data.values())
    if q=='each()':
        if not isinstance(data,list): raise QueryError('cannot each over non-array')
        return data
    if q=='count()':
        if not isinstance(data,list): raise QueryError('cannot use count over non-array')
        return len(data)
    if q.startswith('search(') and q.endswith(')'):
        expr=q[7:-1].strip()
        m=re.fullmatch(r'([\w-]+)\s*(==|!=)\s*(.+)',expr)
        if not m: return []
        key,op,rhs=m.groups()
        try: rhs=json.loads(rhs)
        except: rhs=rhs.strip("'\"")
        found=[]
        def rec(n):
            if isinstance(n,dict):
                if key in n and ((n[key]==rhs) == (op=='==')): found.append(n)
                for x in n.values(): rec(x)
            elif isinstance(n,list):
                for x in n: rec(x)
        rec(data); return found
    if q.startswith('"') and q.endswith('"'): return json.loads(q)
    if q.startswith("'") and q.endswith("'"): return q[1:-1]
    if q in ('true','false','null') or re.fullmatch(r'-?\d+(\.\d+)?',q):
        return json.loads(q)
    # simple equality / arithmetic expressions
    for op in (' == ',' != ',' >= ',' <= ',' + ',' - ',' * ',' / '):
        if op in q:
            a,b=q.split(op,1); av=evalq(data,a); bv=evalq(data,b)
            return {'==':lambda:av==bv,'!=':lambda:av!=bv,'>=':lambda:av>=bv,'<=':lambda:av<=bv,'+':lambda:av+bv,'-':lambda:av-bv,'*':lambda:av*bv,'/':lambda:av/bv}[op.strip()]()
    cur=data
    for part in split_path(q):
        if not part: continue
        if part.startswith('[') and part.endswith(']'):
            content=part[1:-1]
            if ':' in content:
                if not isinstance(cur,list): raise QueryError('range requires array')
                # observed ranges mostly retain the entire array
                lo,hi=(content.split(':',1)+[''])[:2]
                if hi and int(hi)>=len(cur): raise QueryError(f'slice index out of range: {hi}')
                if lo and int(lo)>=len(cur): raise QueryError(f'slice index out of range: {lo}')
                cur=cur[int(lo):] if lo and int(lo)>0 else cur
            else:
                i=int(content)
                if isinstance(cur,list):
                    if i<0 or i>=len(cur): raise QueryError(f'slice index out of range: {i}')
                    cur=cur[i]
                elif isinstance(cur,dict): cur=cur.get(content)
                else: raise QueryError('unexpected type')
        elif isinstance(cur,dict):
            if part not in cur: raise QueryError(f'map key not found: "{part}"')
            cur=cur[part]
        else:
            # dot numeric is a number literal expression
            if isinstance(cur,list) and part.isdigit(): cur=int(part)
            else: raise QueryError(f'unexpected type: expected map, got {type(cur).__name__}')
    return cur

def main():
    args=sys.argv[1:]
    if args and args[0]=='version': print('3.11.0'); return 0
    if args and args[0]=='query': args=args[1:]
    parser=argparse.ArgumentParser(prog='dasel',add_help=True)
    parser.add_argument('query',nargs='?'); parser.add_argument('-i','--in',dest='infmt',default='json'); parser.add_argument('-o','--out',dest='outfmt'); parser.add_argument('--root',action='store_true'); parser.add_argument('--compact',action='store_true'); parser.add_argument('--read-flag',action='append',default=[]); parser.add_argument('--write-flag',action='append',default=[]); parser.add_argument('--rw-flag',action='append',default=[]); parser.add_argument('--var',action='append',default=[])
    try: ns=parser.parse_args(args)
    except SystemExit as e: return e.code
    raw=sys.stdin.read()
    try:
        inf=ns.infmt.lower(); delimiter=','
        for f in ns.read_flag+ns.rw_flag:
            if f.startswith('csv-delimiter='): delimiter=f.split('=',1)[1]
        if inf=='json': data=json.loads(raw)
        elif inf=='csv': data=parse_csv(raw,delimiter)
        elif inf=='toml':
            import tomllib; data=tomllib.loads(raw)
        elif inf in ('yaml','yml'):
            # Basic YAML scalar/object support
            data=parse_simple_yaml(raw)
        else: raise QueryError('unsupported input format')
        result=evalq(data,ns.query or '')
        if ns.root: result=data
        outf=(ns.outfmt or inf).lower()
        if outf=='csv': out=write_csv(result,delimiter)
        else:
            out=json.dumps(result,ensure_ascii=False,separators=(',',':') if ns.compact else None,indent=None if ns.compact else 4)
            if not ns.compact: out+='\n'
        sys.stdout.write(out); return 0
    except Exception as e:
        msg=str(e)
        if isinstance(e,QueryError):
            if msg.startswith('map key not found'): msg='execution error when processing ast.PropertyExpr: '+msg
            elif msg.startswith('unexpected type'): msg='execution error when processing ast.ChainedExpr: error executing expression: execution error when processing ast.PropertyExpr: '+msg
            else: msg='execution error when processing ast.CallExpr: '+msg
            msg='error executing selector: '+msg
        else: msg='error: '+msg
        sys.stderr.write('dasel: error: '+msg+'\n'); return 1

def parse_simple_yaml(s):
    # Lightweight indentation-based mappings, sufficient for common documents.
    lines=[(len(x)-len(x.lstrip()),x.strip()) for x in s.splitlines() if x.strip() and not x.lstrip().startswith('#')]
    if not lines: return None
    root={}; stack=[(-1,root)]
    def scalar(x):
        if x in ('true','True'): return True
        if x in ('false','False'): return False
        if x in ('null','~'): return None
        try: return json.loads(x)
        except: return x.strip("'\"")
    for ind,line in lines:
        if ':' not in line: continue
        k,v=line.split(':',1); k=k.strip().strip("'\""); v=v.strip()
        while stack and stack[-1][0]>=ind: stack.pop()
        parent=stack[-1][1]
        if v: parent[k]=scalar(v)
        else: parent[k]={}; stack.append((ind,parent[k]))
    return root

if __name__=='__main__': raise SystemExit(main())

