#!/usr/bin/env python3
import sys,json,argparse,re
from csvformat import parse_csv,write_csv

class QueryError(Exception): pass

def walk_recursive(node,key,out):
    if isinstance(node,dict):
        for v in node.values():
            if isinstance(v,dict) and key in v: out.append(v[key])
            walk_recursive(v,key,out)
    elif isinstance(node,list):
        for v in node:
            if isinstance(v,dict) and key in v: out.append(v[key])
            walk_recursive(v,key,out)

def split_path(s):
    parts=[]; cur=''; quote=None; esc=False
    for c in s:
        if quote:
            cur+=c
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        elif c in '\"\'': quote=c; cur+=c
        elif c=='[':
            if depth==0 and cur:
                parts.append(cur); cur=''
            depth+=1; cur+=c
        elif c==']': depth-=1; cur+=c
        elif c=='.' and depth==0: parts.append(cur); cur=''
        else: cur+=c
    if cur: parts.append(cur)
    return parts

def evalq(data,q):
    q=q.strip()
    if not q: return data
    # Assignment expressions update the addressed value in the input tree and
    # evaluate to the newly assigned value.
    m = re.match(r'^(.*?)\s*=\s*(?!=)(.+)$', q, re.S)
    if m and '==' not in q and '!=' not in q and '>=' not in q and '<=' not in q:
        path, rhs = m.group(1).strip(), m.group(2).strip()
        value = evalq(data, rhs)
        parts = split_path(path)
        if not parts:
            raise QueryError('cannot assign to root')
        parent = data
        for part in parts[:-1]:
            if part.startswith('[') and part.endswith(']'):
                idx = int(part[1:-1])
                if not isinstance(parent, list) or idx < 0 or idx >= len(parent):
                    raise QueryError(f'slice index out of range: {idx}')
                parent = parent[idx]
            elif isinstance(parent, dict) and part in parent:
                parent = parent[part]
            else:
                raise QueryError(f'map key not found: "{part}"')
        last = parts[-1]
        if last.startswith('[') and last.endswith(']'):
