"""TOML output encoder for the common data model types."""
import json
import re


def parse_toml(text):
    """Parse common TOML values, with tomllib when available."""
    try:
        import tomllib
        return tomllib.loads(text)
    except ImportError:
        pass
    root = {}
    current = root
    def value(s):
        s = s.strip()
        if s.startswith("'") and s.endswith("'"): return s[1:-1]
        if s.startswith('"'):
            try: return json.loads(s)
            except Exception: return s.strip('"')
        if s == "true": return True
        if s == "false": return False
        if s.startswith("[") and s.endswith("]"):
            body=s[1:-1].strip()
            if not body: return []
            # Split inline arrays outside quoted strings.
            vals=[]; start=0; quote=None; esc=False
            for i,c in enumerate(body):
                if quote:
                    if esc: esc=False
                    elif c == "\\": esc=True
                    elif c == quote: quote=None
                elif c in "'\"": quote=c
                elif c == ",": vals.append(value(body[start:i])); start=i+1
            vals.append(value(body[start:]))
            return vals
        try: return int(s, 0)
        except Exception:
            try: return float(s)
            except Exception: return s
    for line in text.splitlines():
        line=line.strip()
        if not line or line.startswith("#"): continue
        if line.startswith("[[") and line.endswith("]]" ):
            path=[x.strip().strip('"\'') for x in line[2:-2].split('.')]
            parent=root
            for key in path[:-1]: parent=parent.setdefault(key,{})
            arr=parent.setdefault(path[-1],[]); obj={}; arr.append(obj); current=obj
        elif line.startswith("[") and line.endswith("]"):
            path=[x.strip().strip('"\'') for x in line[1:-1].split('.')]
            current=root
            for key in path: current=current.setdefault(key,{})
        elif "=" in line:
            k,v=line.split("=",1); current[k.strip().strip('"\'')]=value(v.split("#",1)[0].strip())
    return root


def _key(key):
    key = str(key)
    return key if re.fullmatch(r"[A-Za-z0-9_-]+", key) else json.dumps(key, ensure_ascii=False)


def _val(v):
    if v is None:
        raise ValueError("toml encode failed: toml: cannot encode a nil interface")
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, str):
        if "'" not in v and "\n" not in v and "\r" not in v:
            return "'" + v + "'"
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, (int, float)):
        return str(v)
    if isinstance(v, list):
        if any(isinstance(x, dict) for x in v):
            return None
        return "[" + ", ".join(_val(x) for x in v) + "]"
    if isinstance(v, dict):
        return None
    raise ValueError("unsupported TOML value")


def dump_toml(data):
    if data is None:
        raise ValueError("toml encode failed: toml: cannot encode a nil interface")
    if isinstance(data, list):
        value = _val(data)
        if value is not None:
            return value + "\n"
        raise ValueError("toml encode failed: toml: cannot encode a slice")
    if not isinstance(data, dict):
        return _val(data) + "\n"
    lines = []
    def table(obj, path, array_table=False):
        if path:
            lines.append(("[[" if array_table else "[") + ".".join(_key(x) for x in path) + ("]]" if array_table else "]"))
        scalars = []
        sections = []
        for k, v in obj.items():
            if isinstance(v, dict): sections.append((k, v, False))
            elif isinstance(v, list) and any(isinstance(x, dict) for x in v): sections.append((k, v, True))
            else: scalars.append((k, v))
        for k, v in scalars:
            value = _val(v)
            if value is None:
                raise ValueError("toml encode failed: toml: cannot encode a slice")
            lines.append(f"{_key(k)} = {value}")
        for k, v, is_array in sections:
            if lines and lines[-1] != "": lines.append("")
            if is_array:
                for j, item in enumerate(v):
