"""HCL body serializer for maps, objects, and primitive arrays."""
import json


def _kind(v):
    if v is None: return "null"
    if isinstance(v, dict): return "map"
    if isinstance(v, list): return "array"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, float): return "float"
    if isinstance(v, str): return "string"
    return type(v).__name__


def _value(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v, (int, float)): return str(v)
    if isinstance(v, list): return "[" + ", ".join(_value(x) for x in v if not isinstance(x, dict)) + "]"
    raise ValueError("cannot encode HCL value")


def dump_hcl(value):
    if not isinstance(value, dict):
        raise ValueError(f"hcl body is expected to be a map, got {_kind(value)}")
    lines = []
    def body(obj, level):
        pad = " " * level
        for k, v in obj.items():
            if isinstance(v, dict):
                lines.append(f"{pad}{k} {{")
                body(v, level + 2)
                lines.append(f"{pad}}}")
            elif isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                for item in v:
                    lines.append(f"{pad}{k} {{")
                    body(item, level + 2)
                    lines.append(f"{pad}}}")
            elif isinstance(v, list) and (not v or all(not isinstance(x, dict) for x in v)):
                if v: lines.append(f"{pad}{k} = {_value(v)}")
            else:
                lines.append(f"{pad}{k} = {_value(v)}")
    body(value, 0)
    return "\n".join(lines) + ("\n" if lines else "")


def _split_values(text):
    parts=[]; start=0; depth=0; quoted=False; escaped=False
    for i,ch in enumerate(text):
        if quoted:
            if escaped: escaped=False
            elif ch=='\\\\': escaped=True
            elif ch=='"': quoted=False
        elif ch=='"': quoted=True
        elif ch in '[{(': depth+=1
        elif ch in ']})': depth-=1
        elif ch==',' and depth==0: parts.append(text[start:i].strip()); start=i+1
    parts.append(text[start:].strip())
    return [x for x in parts if x]

def _parse_value(text):
    text=text.strip()
    if not text: return None
    if text.startswith('[') and text.endswith(']'):
        return [_parse_value(x) for x in _split_values(text[1:-1])]
    if text in ('true','false'): return text=='true'
    if text=='null': return None
    try: return json.loads(text)
    except Exception: pass
    try: return int(text,0)
    except Exception: pass
    try: return float(text)
    except Exception: return text

def parse_hcl(text):
    """Parse simple HCL assignments and nested blocks."""
    root={}; stack=[root]
    for raw in text.splitlines():
        line=raw.strip()
        if not line or line.startswith('#') or line.startswith('//'): continue
        # Remove trailing comments outside quotes.
        quote=False; escaped=False; cut=len(line)
        for i,ch in enumerate(line):
            if quote:
                if escaped: escaped=False
                elif ch=='\\\\': escaped=True
                elif ch=='"': quote=False
            elif ch=='"': quote=True
            elif ch=='#': cut=i; break
        line=line[:cut].strip()
        if not line: continue
        if line=='}':
            if len(stack)>1: stack.pop()
            continue
        if line.endswith('{'):
            header=line[:-1].strip().split()
            if not header: continue
            key=header[0].strip('"'); item={}; parent=stack[-1]
            if len(header)>1:
                label=header[1].strip('"')
                if key not in parent or not isinstance(parent[key],dict): parent[key]={}
                parent[key][label]=item
            elif key not in parent: parent[key]=item
            elif isinstance(parent[key],list): parent[key].append(item)
            else: parent[key]=[parent[key],item]
            stack.append(item); continue
        if '=' in line:
            key,value=line.split('=',1); stack[-1][key.strip().strip('"')]=_parse_value(value)
    return root

